  const w = img.width;
  const h = img.height;
  const data = img.data;
  const row = Math.floor(h * 0.5);
  let r = 0;
  let g = 0;
  let b = 0;
  let n = 0;
  if (data instanceof Uint16Array || data instanceof Float32Array) {
    const half = data instanceof Uint16Array;
    for (let x = 0; x < w; x += 4) {
      const i = (row * w + x) * 4;
      const cr = data[i] ?? 0;
      const cg = data[i + 1] ?? 0;
      const cb = data[i + 2] ?? 0;
      r += half ? DataUtils.fromHalfFloat(cr) : cr;
      g += half ? DataUtils.fromHalfFloat(cg) : cg;
