    [0.24, 0.68], [0.44, 0.68], [0.44, 0.82], [0.24, 0.82], [0.24, 0.96], [0.44, 0.96], [0.44, 1.1], [0.24, 1.1], [0.3, 1.3], [0.5, 1.42], [0.12, 1.5], [0, 1.25],
  ];
